export function icon(name) {
  const d = ICON_PATHS[name];
  if (!d) {
    return `<svg class="ico" viewBox="${VIEW_BOX}" width="1em" height="1em" fill="none" stroke="currentColor" stroke-width="80" aria-hidden="true"><rect x="-800" y="-800" width="640" height="640" rx="80"/></svg>`;
  }
  return `<svg class="ico" viewBox="${VIEW_BOX}" width="1em" height="1em" fill="currentColor" aria-hidden="true"><path d="${d}"/></svg>`;
}

export const ICON_NAMES = Object.keys(ICON_PATHS);
